def test_number_formats_mixed(run):
    r = run(args=['a=1', 'b=1.0', 'c=1e2', 'd=0.000001', 'e=1e21', 'f=1e-7', 'g=123456.789', 'h=0.1e1', 'i=-0.0', 'j=1e15', 'k=1e16', 'l=1e17', 'm=2.5e-5'])
    assert r.stdout == b'{"a":1,"b":1,"c":100,"d":1e-06,"e":1e+21,"f":1e-07,"g":123456.789,"h":1,"i":-0,"j":1000000000000000,"k":1e+16,"l":1e+17,"m":2.5e-05}\n'
    assert r.stderr == b''
    assert r.returncode == 0
